/* Inline Script 20 */

      jQuery(document).ready(function($) {
         $(document).on('click', '[data-fancybox="gallery"]', function() {
            setTimeout(function() {
               $('.fancybox__slide.is-selected img.fancybox__image').each(function() {
                  console.log("step 1");
                  const fullSrc = $(this).attr('src');

                  const ext = fullSrc.split('.').pop().toLowerCase();
                  const base = fullSrc.replace(/\.\w+$/, '');
                  const customSrc = `${base}-768x576.${ext}`;

                  // Check if 768x576 version exists
                  $.ajax({
                     url: customSrc,
                     type: 'HEAD',
                     success: () => {
                        // If found, use the 768x576 version
                        $(this).attr('src', customSrc);
                        $(this).attr('srcset', `${customSrc} 768w`);
                        $(this).attr('sizes', '768px');
                        console.log("750 load");

                     },
                     error: () => {
                        // If not found, fallback to original
                        $(this).attr('src', fullSrc);
                        console.log("eror");

                     },
                     complete: () => {
                        // Final image properties (excluding lazy load)
                        $(this).attr('decoding', 'async');
                        $(this).css({
                           width: '100%',
                           height: 'auto'
                        });
                     }
                  });
               });
            }, 300);
         });
      });
   

