/* Inline Script 22 */

      jQuery(document).ready(function($) {
         $('area[href^="#e-n-accordion-item-"]').on('click', function(e) {
            e.preventDefault();

            var targetID = $(this).attr('href'); // e.g., #e-n-accordion-item-2010
            var $target = $(targetID); // Target accordion element

            // Step 1: Close all
            $('details.e-n-accordion-item').removeAttr('open');

            // Update the URL hash without reloading
            history.pushState(null, null, targetID);

            // Step 2: Open target accordion
            $target.attr('open', true);

            // Step 3: Wait for accordion to expand (layout shift), then scroll smoothly
            setTimeout(function() {
               var targetOffset = $target.offset().top - 400; // Adjust offset as needed

               $('html, body').animate({
                  scrollTop: targetOffset
               }, 100); // Smooth scroll duration
            }, 100); // Delay for layout to settle (can tweak to 150–200 if needed)
         });
      });
   

