document.querySelectorAll('.e-n-accordion-item summary').forEach(summary => {
  summary.addEventListener('click', function () {
    const details = this.parentNode;

    // Wait until browser expands <details>
    setTimeout(() => {
      if (details.hasAttribute('open')) {
        const y = this.getBoundingClientRect().top + window.scrollY;
        window.scrollTo({
          top: y - 170,  // adjust offset (e.g. header height)
          behavior: 'smooth'
        });

      }
    }, 400); // delay should match accordion expand animation
  });
});





